<dialog x-ref="onuDialog" class="onu-inspector" aria-labelledby="onu-inspector-title" @cancel.prevent="closeOnuInspector()" @click="if($event.target===$refs.onuDialog)closeOnuInspector()">
<template x-if="inspectedOnu"><div class="onu-inspector-shell">
    <header class="onu-inspector-header"><div><h2 id="onu-inspector-title" x-text="onuDisplayName(inspectedOnu).toUpperCase()"></h2><p x-text="detailSubtitle()"></p></div><button class="icon-button" aria-label="Tutup detail ONU" @click="closeOnuInspector()"><i data-lucide="x"></i></button></header>
    <nav class="onu-inspector-tabs" role="tablist" aria-label="Detail ONU"><template x-for="(tab,index) in detailAvailableTabs()" :key="tab.key"><button role="tab" :id="'onu-tab-'+tab.key" :aria-controls="'onu-pane-'+tab.key" :aria-selected="detailTab===tab.key" :tabindex="detailTab===tab.key?0:-1" @click="selectOnuTab(tab.key)" @keydown="onuTabKey($event,index)" x-text="tab.name"></button></template></nav>
    <div class="onu-inspector-body" id="onu-details-panel" :class="{'is-loading':detailInitialLoading||(detailBusy&&!detailSections[detailTab])}" :aria-busy="detailInitialLoading||detailBusy">
        <p class="onu-detail-error" role="alert" x-show="detailError||error" x-text="detailError||error"></p>
        <div class="notice" role="status" x-show="rebootState?.id===inspectedOnu?.id"><span x-text="rebootState?.waiting?'Menunggu sesi OLT tersedia. Reboot belum dikirim (maksimal 90 detik).':'Mengirim permintaan reboot ke OLT…'"></span><button type="button" class="btn secondary" x-show="rebootState?.waiting" @click="cancelRebootWait()">Batalkan reboot</button></div>
        <div class="notice" x-show="detailMeta.source==='simulator'">Mode simulator · data berasal dari simulator lokal.</div>
        <div class="notice" x-show="isYotc(oltForOnu(inspectedOnu))">Snapshot monitoring YOTC C1600. Gunakan Sync pada kartu OLT untuk mengambil data perangkat terbaru.</div>
        <div class="onu-live-bar"><span class="status-badge" :class="phaseClass(detailValue('phase_state'))" x-text="'● '+onuState(detailValue('phase_state'))"></span><span class="muted small" x-text="detailAge()"></span><span class="onu-live-actions" x-show="!isYotc(oltForOnu(inspectedOnu))"><button class="btn secondary" :aria-pressed="detailAuto" @click="toggleOnuAuto()" x-text="detailAuto?'Ⅱ Otomatis':'▶ Otomatis'"></button><button class="icon-button" aria-label="Refresh detail ONU" @click="refreshOnuSection()" :disabled="detailBusy"><i data-lucide="refresh-cw" :class="{'spinning':detailBusy}"></i></button></span></div>
        <p class="muted small" role="status" x-show="detailBusy">Membaca ONU dari OLT…</p>
        <details class="onu-read-notes" x-show="detailSections[detailTab]?.warnings?.length"><summary>Catatan pembacaan firmware</summary><template x-for="(note,index) in detailSections[detailTab]?.warnings||[]" :key="index"><p class="small muted" x-text="note"></p></template></details>
        @include('partials.skeleton',['show'=>'detailInitialLoading||(detailBusy&&!detailSections[detailTab])'])
        <section id="onu-pane-info" role="tabpanel" aria-labelledby="onu-tab-info" x-show="detailTab==='info'">
            <form class="onu-tag-bar" @submit.prevent="detailSetTag(null)"><i data-lucide="tags"></i><template x-for="tag in inspectedOnu.tags" :key="tag.id"><span class="tag"><span x-text="tag.tag_name"></span><button type="button" x-show="db.permissions.tags" @click="detailSetTag(tag,true)" :aria-label="'Hapus tag '+tag.tag_name">×</button></span></template><input x-show="db.permissions.tags" x-model="detailTag" placeholder="Tambah tag..." aria-label="Tambah tag ONU" list="onu-tag-suggestions"><datalist id="onu-tag-suggestions"><template x-for="tag in db.tags" :key="tag.id"><option :value="tag.tag_name"></option></template></datalist></form>
            <div class="onu-info-grid">
                <article class="onu-detail-card onu-pon-traffic" x-show="isYotc(oltForOnu(inspectedOnu))">
                    <div class="onu-card-title"><h3>Traffic PON (gabungan)</h3><button type="button" class="btn secondary" x-show="detailPonTrafficPort()" @click="openDetailPonTraffic()"><i data-lucide="activity"></i><span x-text="'Traffic PON '+trafficPonKey(detailPonTrafficPort())+' (gabungan)'"></span></button></div>
                    <p class="muted small" x-show="!onuSupports(inspectedOnu,'onu_traffic')">Traffic per ONU belum tersedia untuk YOTC C1600. Grafik PON mencakup seluruh ONU pada port yang sama.</p>
                    <p class="muted small" x-show="onuSupports(inspectedOnu,'onu_traffic')">Traffic per ONU tersedia via PPPoE MikroTik (<span class="mono" x-text="inspectedOnu.pppoe_user||'otomatis'"></span> · <strong x-text="traffic(inspectedOnu)"></strong>). Gunakan tombol <strong>Traffic</strong> di bawah untuk grafik per ONU, atau tombol di atas untuk grafik PON gabungan.</p>
                    <p class="muted small" x-show="!detailPonTrafficPort()">Traffic PON ini belum diaktifkan.</p>
                </article>
                <article class="onu-detail-card"><div class="onu-card-title"><h3>Sinyal optik</h3><button class="text-button" @click="showOnuPanel('optical')">Riwayat redaman</button></div><div class="onu-optical-metrics">
                    <div><span>RX Power</span><strong :class="signalClass({rx_power:detailValue('rx_power')})" x-text="rx(detailValue('rx_power'))"></strong><small class="status-badge" :class="detailValue('rx_power')==null?'':detailValue('rx_power')<=db.threshold?'phase-los':'online'" x-text="detailValue('rx_power')==null?'Belum tersedia':detailValue('rx_power')<=db.threshold?'Buruk':detailValue('rx_power')< -25?'Waspada':'Baik'"></small></div>
                    <div><span>TX Power</span><strong x-text="rx(detailValue('tx_power'))"></strong><small class="muted" x-text="detailValue('tx_power')==null?'Belum tersedia':'Daya pancar ONU'"></small></div>
                    <div><span>RX di OLT</span><strong x-text="rx(detailValue('olt_rx_power'))"></strong><small class="muted">Arah upstream</small></div>
                </div><p class="onu-card-footnote">RX Power diukur di ONU (arah downstream), RX di OLT diukur di OLT (arah upstream).</p></article>
                <article class="onu-detail-card"><div class="onu-card-title"><h3>Koneksi</h3><button class="text-button" @click="showOnuPanel('status')">Riwayat status</button></div><dl class="onu-kv"><div><dt>Terakhir online</dt><dd x-text="detailValue('last_online_at')?dateTime(detailValue('last_online_at')):'Belum tersedia'"></dd></div><div><dt>Terakhir offline</dt><dd x-text="detailValue('last_offline_at')?dateTime(detailValue('last_offline_at')):'Belum tersedia'"></dd></div><div><dt>Sebab terakhir</dt><dd><span class="status-badge" x-text="'● '+(detailValue('last_down_cause')||'Tidak diketahui')"></span></dd></div></dl></article>
                <article class="onu-detail-card"><div class="onu-card-title"><h3>Perangkat</h3><i data-lucide="router"></i></div><dl class="onu-kv">
                    <div><dt>Serial</dt><dd class="mono" x-text="inspectedOnu.sn"></dd></div><div x-show="inspectedOnu.pppoe_user"><dt>PPPoE</dt><dd class="mono" x-text="inspectedOnu.pppoe_user"></dd></div><div><dt>Tipe terbaca</dt><dd x-text="detailValue('reported_type')||'Belum tersedia'"></dd></div><div><dt>Tipe dikonfigurasi</dt><dd x-text="detailValue('configured_type')||inspectedOnu.onu_type||'Belum tersedia'"></dd></div><div><dt>Jarak</dt><dd x-text="detailValue('distance_m')==null?'Belum tersedia':detailValue('distance_m')+' m'"></dd></div><div><dt>Kartu</dt><dd x-text="detailMeta.board?.real_type||detailMeta.board?.type||'Belum tersedia'"></dd></div><div><dt>Software</dt><dd x-text="detailValue('software')||'Belum tersedia'"></dd></div><div><dt>Deskripsi</dt><dd x-text="detailData('info').description||detailMeta.description||'ONU-'+onuPosition(inspectedOnu)"></dd></div>
                </dl></article>
                <article class="onu-detail-card"><div class="onu-card-title"><h3>ODP</h3><i data-lucide="map-pin"></i></div><div class="onu-odp-empty"><i data-lucide="git-fork"></i><p x-text="detailMeta.odp?detailMeta.odp.name+' · Port '+detailMeta.odp.port:'Belum terhubung ke ODP.'"></p><button class="btn secondary" x-show="db.permissions.operate&&db.permissions.maps" @click="showOnuPanel('edit')">Hubungkan ke ODP</button></div></article>
            </div>
            <details class="onu-position-history"><summary>Riwayat posisi <span class="muted" x-text="onuPosition(inspectedOnu)+' · ditambah, dihapus, serial berubah, hilang dari OLT'"></span></summary><p class="small muted">Catatan inventaris pada posisi ini; waktu terakhir terlihat bukan waktu pasti penghapusan.</p><template x-for="entry in detailMeta.position_history||[]" :key="entry.id"><p class="small"><span class="mono" x-text="entry.sn"></span> · <span x-text="entry.is_present?'Terdaftar':'Tidak ada pada inventaris aktif'"></span> · <span x-text="dateTime(entry.created_at)"></span></p></template></details>
        </section>
        <section id="onu-pane-wan" role="tabpanel" aria-labelledby="onu-tab-wan" x-show="detailTab==='wan'">
            <div class="onu-section-heading"><div><h3>Konfigurasi WAN</h3><p class="muted small" x-text="detailItems().length+' konfigurasi · '+detailUpCount()+' terhubung · '+detailAge()"></p></div><div class="module-toolbar"><button class="btn secondary" @click="refreshOnuSection('wan')" :disabled="detailBusy">&gt;_ Get WAN IP</button><button class="btn primary" x-show="db.permissions.operate && onuSupports(inspectedOnu,'onu_configuration')" @click="editOnuService('wan')">+ Tambah PPPoE</button></div></div>
            <template x-for="item in detailData('wan').items||[]" :key="item.id"><article class="onu-detail-card onu-wan-card"><div class="onu-card-title"><div><h3 x-text="item.username||onuDisplayName(inspectedOnu)"></h3><p class="muted small" x-text="'WAN '+item.id+' · '+(item.vlan_profile||item.profile||'OMCI')"></p></div><span class="status-badge" x-text="(item.mode||'WAN').toUpperCase()"></span><span class="status-badge" :class="detailStatus(item.status)?'online':''" x-text="item.status||'Status belum tersedia'"></span><button class="icon-button" aria-label="Edit WAN" x-show="db.permissions.operate && onuSupports(inspectedOnu,'onu_configuration')" @click="editOnuService('wan',item)"><i data-lucide="pencil"></i></button><button class="icon-button red-text" aria-label="Hapus WAN" x-show="db.permissions.operate && onuSupports(inspectedOnu,'onu_configuration')" @click="if(confirm('Hapus WAN '+item.id+' dari ONU?'))executeOnuConfiguration({kind:'wan',id:item.id,delete:true,confirmed:true})"><i data-lucide="trash-2"></i></button></div><dl class="onu-kv"><div><dt>Alamat IP</dt><dd class="mono" x-text="item.ip||'Belum tersedia'"></dd></div><div><dt>Password</dt><dd><span x-text="detailSecrets['wan:'+item.id]||(item.has_password?'••••••••':'Belum tersedia')"></span><button class="icon-button" aria-label="Lihat password WAN" x-show="db.permissions.operate&&onuSupports(inspectedOnu,'onu_configuration')&&item.has_password" @click="revealOnuSecret(item)"><i data-lucide="eye"></i></button></dd></div><div><dt>VLAN</dt><dd x-text="item.vlan_id??item.vlan_profile??'Belum tersedia'"></dd></div><div><dt>OMCI</dt><dd x-text="item.omci||'WAN '+item.id"></dd></div></dl></article></template>
            <div class="onu-empty" x-show="!detailData('wan').items?.length">Konfigurasi WAN belum tersedia dari OLT.</div><div class="modal-actions"><button class="btn secondary" x-show="db.permissions.cli && onuSupports(inspectedOnu,'onu_configuration')" @click="showOnuPanel('config')">Konfigurasi WAN lengkap</button></div>
        </section>
        <section id="onu-pane-ethernet" role="tabpanel" aria-labelledby="onu-tab-ethernet" x-show="detailTab==='ethernet'"><div class="onu-section-heading"><div><h3>Port Ethernet (UNI)</h3><p class="small muted" x-text="detailItems().length+' port · '+detailUpCount()+' aktif · '+detailAge()"></p></div></div><div class="onu-info-grid"><template x-for="item in detailData('ethernet').items||[]" :key="item.id"><article class="onu-detail-card"><div class="onu-card-title"><h3 x-text="'Port '+item.id"></h3><span class="status-badge" :class="detailStatus(item.operational)?'online':'phase-los'" x-text="item.operational?(detailStatus(item.operational)?'● Aktif':'● Down'):'Belum tersedia'"></span><button class="icon-button" aria-label="Edit port Ethernet" x-show="db.permissions.operate && onuSupports(inspectedOnu,'onu_configuration')" @click="editOnuService('ethernet',item)"><i data-lucide="pencil"></i></button></div><p class="small muted" x-text="'Auto-Negotiation · '+(item.auto_negotiation||'Belum tersedia')"></p><dl class="onu-kv"><div><dt>Admin</dt><dd x-text="item.admin||'—'"></dd></div><div><dt>Operasional</dt><dd x-text="item.operational||'—'"></dd></div><div><dt>Kecepatan aktual</dt><dd x-text="item.speed||'—'"></dd></div></dl><details><summary>Rincian</summary><dl class="onu-kv"><template x-for="(value,key) in item.details||{}" :key="key"><div><dt x-text="key"></dt><dd x-text="value"></dd></div></template></dl></details></article></template></div><div class="onu-empty" x-show="!detailData('ethernet').items?.length">Daftar port belum tersedia. Jumlah port mengikuti hasil pembacaan perangkat.</div></section>
        <section id="onu-pane-iphost" role="tabpanel" aria-labelledby="onu-tab-iphost" x-show="detailTab==='iphost'"><h3>IP host / Management ONT</h3><div class="onu-info-grid"><template x-for="item in detailData('iphost').items||[]" :key="item.id"><article class="onu-detail-card"><h3 x-text="'IP host '+item.id"></h3><dl class="onu-kv"><template x-for="key in ['ip','mask','gateway','dns','mode','status']" :key="key"><div><dt x-text="key.toUpperCase()"></dt><dd x-text="item[key]||'Belum tersedia'"></dd></div></template></dl></article></template></div><div class="onu-empty" x-show="!detailData('iphost').items?.length">Informasi IP host belum tersedia dari firmware.</div></section>
        <section id="onu-pane-wifi" role="tabpanel" aria-labelledby="onu-tab-wifi" x-show="detailTab==='wifi'"><div class="onu-section-heading"><div><h3>SSID WiFi</h3><p class="small muted" x-text="detailItems().length+' SSID · '+detailUpCount()+' aktif · '+detailAge()"></p></div></div><div class="onu-info-grid"><template x-for="item in detailData('wifi').items||[]" :key="item.id"><article class="onu-detail-card"><div class="onu-card-title"><h3 x-text="'SSID '+item.id"></h3><span class="status-badge" :class="detailStatus(item.admin)?'online':''" x-text="item.admin?(detailStatus(item.admin)?'● Aktif':'● Nonaktif'):'Belum tersedia'"></span><button class="icon-button" aria-label="Edit SSID WiFi" x-show="db.permissions.operate && onuSupports(inspectedOnu,'onu_configuration')" @click="editOnuService('wifi',item)"><i data-lucide="pencil"></i></button></div><p class="onu-ssid-name" x-text="item.name||'Tanpa nama'"></p><dl class="onu-kv"><template x-for="field in [{key:'security',label:'Keamanan'},{key:'encryption',label:'Enkripsi'},{key:'max_users',label:'Maks. pengguna'},{key:'connected',label:'Terhubung'},{key:'visibility',label:'Visibilitas'},{key:'isolation',label:'Isolasi'}]" :key="field.key"><div><dt x-text="field.label"></dt><dd x-text="item[field.key]??'Belum tersedia'"></dd></div></template><div><dt>Password</dt><dd><span x-text="detailSecrets['wifi:'+item.id]||(item.has_password?'••••••••':'Belum tersedia')"></span><button class="icon-button" aria-label="Lihat password WiFi" x-show="db.permissions.operate&&onuSupports(inspectedOnu,'onu_configuration')&&item.has_password" @click="revealOnuSecret(item)"><i data-lucide="eye"></i></button></dd></div></dl></article></template></div><div class="onu-empty" x-show="!detailData('wifi').items?.length">SSID belum tersedia dari OLT. ONU dapat tidak mendukung pembacaan WiFi melalui OMCI.</div></section>
        <section class="onu-detail-card onu-extra-panel" x-show="detailPanel==='edit'"><div class="onu-card-title"><h3>Edit ONU</h3><button class="icon-button" aria-label="Tutup form edit" @click="detailPanel=''"><i data-lucide="x"></i></button></div><form class="form-grid" @submit.prevent="renameOnu()"><label>Nama baru ONU<input x-model="onuNameDraft" maxlength="80" required pattern="[A-Za-z0-9_.()-]+"></label><button class="btn primary" :disabled="busy">Simpan nama ke OLT</button></form><form class="form-grid" @submit.prevent="if(confirm('Ubah deskripsi ONU di OLT?'))executeOnuConfiguration({kind:'description',description:detailDescription,confirmed:true})"><label>Deskripsi<input x-model="detailDescription" maxlength="200" required></label><button class="btn secondary" :disabled="detailBusy">Simpan deskripsi ke OLT</button></form><form class="form-grid" @submit.prevent="saveOnuLocation()" x-show="db.permissions.maps"><label>Latitude pelanggan<input type="number" step="any" x-model.number="onuLocationDraft.latitude" min="-90" max="90" required></label><label>Longitude pelanggan<input type="number" step="any" x-model.number="onuLocationDraft.longitude" min="-180" max="180" required></label><button class="btn secondary" :disabled="busy">Simpan lokasi pelanggan</button></form><form class="form-grid" @submit.prevent="detailAssignOdp()" x-show="db.permissions.maps"><label>ODP<select x-model="detailOdp.node_id" required><option value="">Pilih ODP</option><template x-for="node in detailNodes" :key="node.id"><option :value="node.id" x-text="node.name"></option></template></select></label><label>Port ODP<input type="number" min="1" max="1024" x-model.number="detailOdp.port_number" required></label><button class="btn secondary">Hubungkan ke ODP</button></form></section>
        <template x-if="detailEdit"><form class="onu-detail-card onu-extra-panel form-grid" @submit.prevent="saveOnuService()"><h3 x-text="'Konfigurasi '+detailEdit.kind.toUpperCase()"></h3><label x-show="['wan','ethernet','wifi'].includes(detailEdit.kind)">ID<input type="number" min="1" max="64" x-model.number="detailEdit.id" required></label><template x-if="detailEdit.kind==='wan'"><div class="form-grid"><label>Username PPPoE<input x-model="detailEdit.username" required></label><label>Password PPPoE<input type="password" autocomplete="new-password" x-model="detailEdit.password" required></label><label>Profil VLAN OMCI<input x-model="detailEdit.vlan_profile" required></label><label>Host<input type="number" min="1" max="64" x-model.number="detailEdit.host" required></label></div></template><label x-show="detailEdit.kind==='wifi'">Nama SSID<input x-model="detailEdit.name" maxlength="32"></label><label x-show="detailEdit.kind==='wifi'">Password WiFi baru (opsional)<input type="password" autocomplete="new-password" x-model="detailEdit.password" maxlength="64"></label><label x-show="detailEdit.kind==='ethernet'">Admin aktif<input type="checkbox" x-model="detailEdit.enabled"></label><p class="small muted">Perubahan dikirim setelah konfirmasi dan pemeriksaan serial, lalu dibaca ulang dari OLT.</p><div class="modal-actions"><button type="button" class="btn secondary" @click="detailEdit=null">Batal</button><button class="btn primary" :disabled="detailBusy">Terapkan ke ONU</button></div></form></template>
        <section class="onu-detail-card onu-extra-panel" x-show="['status','optical','traffic'].includes(detailPanel)"><div class="onu-card-title"><h3 x-text="detailPanel==='traffic'?'Traffic ONU':detailPanel==='optical'?'Riwayat redaman':'Riwayat status'"></h3><button class="icon-button" aria-label="Refresh riwayat" @click="loadOnuHistory()"><i data-lucide="refresh-cw"></i></button></div><p class="small muted" x-show="detailPanel==='traffic'">Download dari sampel SNMP. Pembaruan mengikuti interval monitor dan ketersediaan counter.</p><svg x-show="['traffic','optical'].includes(detailPanel)&&chartPoints(detailPanel)" viewBox="0 0 600 180" class="onu-history-chart" role="img" :aria-label="detailPanel==='traffic'?'Grafik download ONU':'Grafik RX ONU'"><path d="M20 20V155H580" fill="none" stroke="currentColor" opacity=".25"/><polyline :points="chartPoints(detailPanel)" fill="none" stroke="#60a5fa" stroke-width="3"/></svg><p class="small muted" x-show="!onuHistory||!(onuHistory[detailPanel==='status'?'status':detailPanel==='traffic'?'traffic':'optical']||[]).length">Belum ada sampel tercatat.</p><div class="onu-history-list"><template x-for="(event,index) in (onuHistory?.[detailPanel==='status'?'status':detailPanel==='traffic'?'traffic':'optical']||[]).slice(0,30)" :key="index"><p><span x-text="dateTime(event.observed_at||event.calculated_at||event.created_at)"></span><strong x-text="detailPanel==='status'?onuState(event.phase_state):detailPanel==='traffic'?((event.download_bps??0)/1000000).toFixed(2)+' ↓ / '+((event.upload_bps??0)/1000000).toFixed(2)+' ↑ Mbps':rx(event.rx_power)"></strong></p></template></div></section>
        <section class="onu-detail-card onu-extra-panel" x-show="detailPanel==='config'"><h3>Konfigurasi ONU dari OLT</h3><p class="small muted">Rahasia disamarkan.</p><pre class="onu-config-output" x-text="detailData('config').output||'Belum tersedia'"></pre></section>
    </div>
    <footer class="onu-inspector-footer"><button class="btn primary" x-show="db.permissions.operate && onuSupports(inspectedOnu,'onu_configuration')" @click="openOnuTool(inspectedOnu)"><i data-lucide="settings-2"></i>Konfigurasi Lanjutan</button><button class="btn primary" x-show="db.permissions.operate && onuSupports(inspectedOnu,'onu_configuration')" @click="selectOnuTab('wan')"><i data-lucide="server-cog"></i>Konfigurasi</button><button class="btn secondary" x-show="db.permissions.operate && onuSupports(inspectedOnu,'onu_configuration')" @click="showOnuPanel('edit')"><i data-lucide="pencil"></i>Edit</button><button class="btn secondary" x-show="onuSupports(inspectedOnu,'onu_traffic')" @click="openTraffic('onus',inspectedOnu)"><i data-lucide="activity"></i>Traffic</button><button class="btn secondary" x-show="!isYotc(oltForOnu(inspectedOnu))" @click="detailTab='info';refreshOnuSection('info')" :disabled="detailBusy">&gt;_ Get Status</button><button class="btn secondary" x-show="db.permissions.cli && onuSupports(inspectedOnu,'onu_configuration')" @click="showOnuPanel('config')"><i data-lucide="scroll-text"></i>Show Config</button><details class="onu-actions-menu" x-show="db.permissions.operate && onuSupports(inspectedOnu,'onu_configuration')"><summary class="btn secondary">Tindakan <i data-lucide="chevron-down"></i></summary><div><button @click="detailAction('reboot')">Reboot ONU</button><button @click="detailAction('admin')" x-text="inspectedOnu.admin_state==='disable'?'Aktifkan ONU':'Nonaktifkan ONU'"></button><button class="red-text" @click="detailAction('factory')">Reset Pabrik</button><button class="red-text" @click="detailAction('delete')">Hapus ONU</button></div></details></footer>
</div></template>
</dialog>
